$ErrorActionPreference = 'SilentlyContinue'
$ProgressPreference = 'SilentlyContinue'

function Get-DirSize($path) {
    if (-not (Test-Path -LiteralPath $path)) { return $null }
    try {
        $sum = (Get-ChildItem -LiteralPath $path -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        if ($null -eq $sum) { $sum = 0 }
        return $sum
    } catch { return $null }
}

$c = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'"
Write-Output "=== DISK C: ==="
Write-Output ("Total {0:N1} GB | Used {1:N1} GB | Free {2:N1} GB | FreePct {3:N0}%" -f ($c.Size/1GB), (($c.Size-$c.FreeSpace)/1GB), ($c.FreeSpace/1GB), (($c.FreeSpace/$c.Size)*100))
Write-Output ""

Write-Output "=== CLEANABLE CANDIDATES ==="
$candidates = @(
    @{c='Windows Temp';        p='C:\Windows\Temp'},
    @{c='WinUpdate Download';  p='C:\Windows\SoftwareDistribution\Download'},
    @{c='WinUpdate Cleanup';   p='C:\Windows\WinSxS'},
    @{c='User Temp';           p="$env:LOCALAPPDATA\Temp"},
    @{c='Thumbnails';          p="$env:LOCALAPPDATA\Microsoft\Windows\Explorer"},
    @{c='Chrome Cache';        p="$env:LOCALAPPDATA\Google\Chrome\User Data\Default\Cache"},
    @{c='Edge Cache';          p="$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache"},
    @{c='npm cache';           p="$env:LOCALAPPDATA\npm-cache"},
    @{c='npm cache (roam)';    p="$env:APPDATA\npm-cache"},
    @{c='pnpm store';          p="$env:LOCALAPPDATA\pnpm-store"},
    @{c='Yarn cache';          p="$env:LOCALAPPDATA\Yarn\Cache"},
    @{c='pip cache';           p="$env:LOCALAPPDATA\pip\Cache"},
    @{c='NuGet cache';         p="$env:USERPROFILE\.nuget\packages"},
    @{c='Gradle cache';        p="$env:USERPROFILE\.gradle\caches"},
    @{c='Maven repo';          p="$env:USERPROFILE\.m2\repository"},
    @{c='DSH cache';           p="$env:USERPROFILE\.dsh\cache"},
    @{c='DSH sessions';        p="$env:USERPROFILE\.dsh\sessions"},
    @{c='Recycle Bin';         p='C:\$Recycle.Bin'},
    @{c='WER Reports';         p='C:\ProgramData\Microsoft\Windows\WER'},
    @{c='Delivery Optimiz.';   p='C:\Windows\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization'},
    @{c='INetCache';           p="$env:LOCALAPPDATA\Microsoft\Windows\INetCache"},
    @{c='CrashDumps';          p="$env:LOCALAPPDATA\CrashDumps"}
)
foreach ($item in $candidates) {
    $size = Get-DirSize $item.p
    if ($null -ne $size) {
        Write-Output ("{0,-22} {1,12:N1} MB  {2}" -f $item.c, ($size/1MB), $item.p)
    }
}

Write-Output ""
Write-Output "=== BIG SYSTEM FILES ==="
foreach ($f in @('C:\hiberfil.sys','C:\pagefile.sys','C:\swapfile.sys')) {
    if (Test-Path -LiteralPath $f) {
        $it = Get-Item -LiteralPath $f -Force
        Write-Output ("{0,-22} {1,12:N1} MB  {2}" -f 'sysfile', ($it.Length/1MB), $f)
    }
}
Write-Output "=== SCAN DONE ==="

