powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "
\$ErrorActionPreference='SilentlyContinue'
function Sz(\$p){ try { \$s=(Get-ChildItem -LiteralPath \$p -Recurse -Force -File -EA SilentlyContinue | Measure-Object Length -Sum).Sum; if(\$null -eq \$s){0}else{\$s} } catch {0} }
Write-Output '=== USER TEMP subfolders (top) ==='
Get-ChildItem -LiteralPath \"\$env:LOCALAPPDATA\Temp\" -Force -Directory -EA SilentlyContinue | ForEach-Object { [PSCustomObject]@{MB=[math]::Round((Sz \$_.FullName)/1MB,1); Name=\$_.Name} } | Sort-Object MB -Descending | Select-Object -First 20 | ForEach-Object { '{0,12:N1} MB  {1}' -f \$_.MB, \$_.Name }
Write-Output '=== USER TEMP loose big files (top) ==='
Get-ChildItem -LiteralPath \"\$env:LOCALAPPDATA\Temp\" -Force -File -EA SilentlyContinue | Sort-Object Length -Descending | Select-Object -First 15 | ForEach-Object { '{0,12:N1} MB  {1}' -f (\$_.Length/1MB), \$_.Name }
"

tool_input.content:
$ErrorActionPreference = 'SilentlyContinue'
$t = Join-Path $env:LOCALAPPDATA 'Temp'
$cutoff = [datetime]'2026-11-25 00:00:00'

# Safety: only dsh-workspace-changes-* dirs, directly under Temp, not reparse points, older than cutoff
$all = Get-ChildItem -LiteralPath $t -Force -Directory | Where-Object {
    $_.Name -like 'dsh-workspace-changes-*' -and
    -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -and
    $_.CreationTime -lt $cutoff
}
$targets = @()
foreach ($d in $all) {
    if ($d.FullName.StartsWith($t, [StringComparison]::OrdinalIgnoreCase)) { $targets += $d }
}

# Guard: sanity on count (total snapshots observed = 658)
if ($targets.Count -eq 0 -or $targets.Count -gt 658) {
    Write-Output ("GUARD TRIP: target count {0} outside (0,658]. Aborting." -f $targets.Count)
    exit 1
}

$sum = 0
foreach ($d in $targets) {
    $s = (Get-ChildItem -LiteralPath $d.FullName -Recurse -Force -File | Measure-Object Length -Sum).Sum
    if ($null -eq $s) { $s = 0 }
    $sum += $s
}
Write-Output ("DRY-RUN: {0} dirs, {1:N1} MB to delete (created before {2:yyyy-MM-dd})" -f $targets.Count, ($sum/1MB), $cutoff)

$ok = 0; $fail = 0
foreach ($d in $targets) {
    try { Remove-Item -LiteralPath $d.FullName -Recurse -Force -ErrorAction Stop; $ok++ }
    catch { $fail++ }
}
Write-Output ("RESULT: deleted {0}, failed {1}" -f $ok, $fail)

$remain = Get-ChildItem -LiteralPath $t -Force -Directory | Where-Object { $_.Name -like 'dsh-workspace-changes-*' }
$rs = 0
foreach ($d in $remain) {
    $s = (Get-ChildItem -LiteralPath $d.FullName -Recurse -Force -File | Measure-Object Length -Sum).Sum
    if ($null -eq $s) { $s = 0 }
    $rs += $s
}
Write-Output ("REMAIN: {0} snapshots, {1:N1} MB" -f $remain.Count, ($rs/1MB))
$c = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'"
Write-Output ("FREE C: now {0:N1} GB" -f ($c.FreeSpace/1GB))
Write-Output "=== CLEAN DONE ==="
